const { AndroidConfig, withAndroidManifest, withDangerousMod } = require("expo/config-plugins");
const fs = require("node:fs");
const path = require("node:path");

// Android blocks cleartext connections by default. Two need it:
// - a gateway at ws://<LAN IP> (self-hosted at home, no certificate). Safe:
//   what travels over it is end-to-end encrypted by LinkShell itself;
// - port previews, which load http://127.0.0.1:<port> from the app's own
//   forwarder.

const CONFIG = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by plugins/with-network-security.js. Do not edit. -->
<network-security-config>
  <base-config cleartextTrafficPermitted="true" />
</network-security-config>
`;

module.exports = function withNetworkSecurity(config) {
  config = withDangerousMod(config, [
    "android",
    (config) => {
      const dir = path.join(config.modRequest.platformProjectRoot, "app/src/main/res/xml");
      fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(path.join(dir, "network_security_config.xml"), CONFIG);
      return config;
    },
  ]);
  return withAndroidManifest(config, (config) => {
    const application = AndroidConfig.Manifest.getMainApplicationOrThrow(config.modResults);
    application.$["android:networkSecurityConfig"] = "@xml/network_security_config";
    return config;
  });
};
